package com.app.entity; import jakarta.persistence.*; import lombok.*; import java.time.*;
@Entity @Table(name="society_attendance_corrections") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class SocietyAttendanceCorrection {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="account_id",nullable=false) private Account account;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="attendance_id",nullable=false) private SocietyAttendance attendance;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="requested_by_user_id",nullable=false) private User requestedBy;@Column(nullable=false) private String requestedStatus;private LocalTime requestedCheckIn;private LocalTime requestedCheckOut;@Column(nullable=false,length=500) private String reason;@Column(nullable=false) @Builder.Default private String status="PENDING";@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="reviewed_by_user_id") private User reviewedBy;private LocalDateTime reviewedAt;@Column(nullable=false,updatable=false) @Builder.Default private LocalDateTime createdAt=LocalDateTime.now();}
